import{_ as p,a0 as o,w as r,s as d,ao as l,I as a,x as e,a1 as s,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"如何在最小安裝的 CentOS、RHEL、Rocky Linux 中設置互聯網 | LCTT x X-CMD","titleTemplate":false,"description":"如何在最小安裝的 CentOS、RHEL、Rocky Linux 中設置互聯網 | LCTT (202210) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在最小安裝的 CentOS、RHEL、Rocky Linux 中設置互聯網 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在最小安裝的 CentOS、RHEL、Rocky Linux 中設置互聯網 | LCTT (202210) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202210/20220926 How to Setup Internet in CentOS, RHEL, Rocky Linux Minimal Install","title":"如何在最小安裝的 CentOS、RHEL、Rocky Linux 中設置互聯網","tag":"202210","desc":""},"relativePath":"202210/20220926 How to Setup Internet in CentOS, RHEL, Rocky Linux Minimal Install.md","filePath":"[post].md"}'),u={name:"202210/20220926 How to Setup Internet in CentOS, RHEL, Rocky Linux Minimal Install.md"};function g(k,t,h,c,m,b){const i=o("Link");return r(),d("div",null,[t[23]||(t[23]=l('<h1 id="如何在最小安裝的-centos、rhel、rocky-linux-中設置互聯網" tabindex="-1">如何在最小安裝的 CentOS、RHEL、Rocky Linux 中設置互聯網 <a class="header-anchor" href="#如何在最小安裝的-centos、rhel、rocky-linux-中設置互聯網" aria-label="Permalink to “如何在最小安裝的 CentOS、RHEL、Rocky Linux 中設置互聯網”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202210/10/162428grhkhtayzt4cdh5k.jpg" alt=""></p><blockquote><p>在最小安裝的服務器中設置互聯網或網絡非常容易。本指南將解釋如何在最小安裝的 CentOS、RHEL 和 Rocky Linux 中設置互聯網或網絡。</p></blockquote><p>當你安裝了任何服務器發行版的最小安裝環境，你將沒有任何 GUI 或桌面環境來設置你的網絡或互聯網。因此，當你只能訪問終端時，瞭解如何設置互聯網非常重要。NetworkManager 工具提供了必要的工具，輔以 systemd 服務來完成這項工作。以下是方法。</p><h3 id="在最小安裝的-centos、rhel、rocky-linux-中設置互聯網" tabindex="-1">在最小安裝的 CentOS、RHEL、Rocky Linux 中設置互聯網 <a class="header-anchor" href="#在最小安裝的-centos、rhel、rocky-linux-中設置互聯網" aria-label="Permalink to “在最小安裝的 CentOS、RHEL、Rocky Linux 中設置互聯網”">​</a></h3><p>在你完成了服務器的安裝後，啓動進入服務器終端。理想情況下，你會看到一個終端提示符。使用 root 或管理員賬户登錄。</p>',6)),a("p",null,[t[1]||(t[1]=e("首先，嘗試使用 ",-1)),s(i,{href:"https://linux.die.net/man/1/nmcli"},{default:n(()=>[...t[0]||(t[0]=[e("nmcli",-1)])]),_:1}),t[2]||(t[2]=e(" 檢查網絡接口的狀態和詳細信息。",-1)),t[3]||(t[3]=a("code",null,"nmcli",-1)),t[4]||(t[4]=e(" 是用於控制 NetworkManager 服務的命令列工具。使用以下命令進行檢查。",-1))]),t[24]||(t[24]=l('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nmcli device status</span></span></code></pre></div><p>這將顯示設備名稱、狀態等。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/06/nmcli-device-status.jpg" alt="nmcli device status"></p><p>運行工具 <code>nmtui</code> 來配置網絡接口。</p><p><code>nmtui</code> 是 NetworkManager 工具的一部分，它為你提供了一個友好的用户界面來配置網絡。</p><p>這是 <code>NetworkManager-tui</code> 包的一部分，在你完成最小服務器安裝後默認安裝。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nmtui</span></span></code></pre></div><p>單擊 nmtui 窗口中的“<ruby>編輯連接<rt>Edit a connection</rt></ruby>”。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/06/nmtui-Select-options.jpg" alt="nmtui - 選擇選項"></p><p>選擇接口名稱</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/06/Select-Interface-to-Edit.jpg" alt="選擇要編輯的接口"></p><p>在“<ruby>編輯連接<rt>Edit Connection</rt></ruby>”窗口中，為 IPv4 和 IPv6 選擇“<ruby>自動<rt>Automatic</rt></ruby>”選項。並選擇“<ruby>自動連接<rt>Automatically Connect</rt></ruby>”。完成後按 “OK”。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/06/nmtui-Edit-Connection.jpg" alt="nmtui - 編輯連接"></p>',13)),a("p",null,[t[6]||(t[6]=e("使用以下命令通過 ",-1)),s(i,{href:"https://www.debugpoint.com/2020/12/systemd-systemctl-service/"},{default:n(()=>[...t[5]||(t[5]=[e("systemd systemctl",-1)])]),_:1}),t[7]||(t[7]=e(" 重啓 NetworkManager 服務。",-1))]),t[25]||(t[25]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl restart NetworkManager</span></span></code></pre></div><p>如果一切順利，你可以在最小安裝的 CentOS、RHEL 和 Rocky Linux 服務器中連接到網絡和互聯網。前提是你的網絡有互聯網連接。你可以使用 <code>ping</code> 來驗證它是否正常工作。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/06/setup-internet-minimal-server-CentOS-Rocky-Linux-RHEL.jpg" alt="設置最小化服務器互聯網 - CentOS Rocky Linux RHEL"></p><h3 id="附加技巧-在最小化服務器中設置靜態-ip" tabindex="-1">附加技巧：在最小化服務器中設置靜態 IP <a class="header-anchor" href="#附加技巧-在最小化服務器中設置靜態-ip" aria-label="Permalink to “附加技巧：在最小化服務器中設置靜態 IP”">​</a></h3><p>當你將網絡配置設置為自動時，接口會在你連接到互聯網時動態分配 IP。在你設置局域網的某些情況下，你可能希望將靜態 IP 分配給你的網絡接口。這非常容易。</p><p>打開你的網絡配置腳本。將 <code>ens3</code> 改為為你自己的設備名。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vi /etc/sysconfig/network-scripts/ifcfg-ens3</span></span></code></pre></div><p>在上面的文件中，使用 <code>IPADDR</code> 屬性添加所需的 IP 地址。保存文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>IPADDR=192.168.0.55</span></span></code></pre></div><p>在 <code>/etc/sysconfig/network</code> 中為你的網絡添加網關。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>NETWORKING=yes</span></span>
<span class="line"><span>HOSTNAME=debugpoint</span></span>
<span class="line"><span>GATEWAY=10.1.1.1</span></span></code></pre></div><p>在 <code>/etc/resolv.conf</code> 中添加任意公共 DNS 服務器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nameserver 8.8.8.8</span></span>
<span class="line"><span>nameserver 8.8.4.4</span></span></code></pre></div><p>然後重啓網絡服務。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl restart NetworkManager</span></span></code></pre></div><p>這就完成了靜態 IP 的設置。你還可以使用 <code>ip addr</code> 命令檢查 IP 詳細信息。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>我希望本指南可以幫助你在最小化安裝的服務器中設置網絡、互聯網和靜態 IP。如果你有任何問題，請在評論區告訴我。</p><hr>`,19)),a("p",null,[t[9]||(t[9]=e("via: ",-1)),s(i,{href:"https://www.debugpoint.com/setup-internet-minimal-install-server/"},{default:n(()=>[...t[8]||(t[8]=[e("https://www.debugpoint.com/setup-internet-minimal-install-server/",-1)])]),_:1})]),a("p",null,[t[14]||(t[14]=e("作者：",-1)),s(i,{href:"https://www.debugpoint.com/author/admin1/"},{default:n(()=>[...t[10]||(t[10]=[e("Arindam",-1)])]),_:1}),t[15]||(t[15]=e(" 選題：",-1)),s(i,{href:"https://github.com/lkxed"},{default:n(()=>[...t[11]||(t[11]=[e("lkxed",-1)])]),_:1}),t[16]||(t[16]=e(" 譯者：",-1)),s(i,{href:"https://github.com/geekpi"},{default:n(()=>[...t[12]||(t[12]=[e("geekpi",-1)])]),_:1}),t[17]||(t[17]=e(" 校對：",-1)),s(i,{href:"https://github.com/wxy"},{default:n(()=>[...t[13]||(t[13]=[e("wxy",-1)])]),_:1})]),a("p",null,[t[20]||(t[20]=e("本文由 ",-1)),s(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[18]||(t[18]=[e("LCTT",-1)])]),_:1}),t[21]||(t[21]=e(" 原創編譯，",-1)),s(i,{href:"https://linux.cn/"},{default:n(()=>[...t[19]||(t[19]=[e("Linux中國",-1)])]),_:1}),t[22]||(t[22]=e(" 榮譽推出",-1))])])}const x=p(u,[["render",g]]);export{C as __pageData,x as default};
